import{af as a,z as i,J as t,ab as o}from"./chunks/framework.DOJTDj7A.js";const m=JSON.parse('{"title":"RTK (Real-Time Kinematic)","description":"","frontmatter":{"aside":true},"headers":[],"relativePath":"terminology/positioning/rtk.md","filePath":"terminology/positioning/rtk.md"}'),r={name:"terminology/positioning/rtk.md"};function s(n,e,c,l,d,h){return i(),t("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1792756874000"},[...e[0]||(e[0]=[o('<h1 id="rtk-real-time-kinematic" tabindex="-1">RTK (Real-Time Kinematic) <a class="header-anchor" href="#rtk-real-time-kinematic" aria-label="Permalink to &quot;RTK (Real-Time Kinematic)&quot;">​</a></h1><p>RTK (Real-Time Kinematic) is a technique used to enhance the precision of position data derived from <a href="./gnss">GNSS systems</a>.</p><p>By using a fixed base station with a known location, RTK can provide centimeter-level accuracy.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/OzhNfJ2.png" alt="" width="400" tabindex="0"><figcaption></figcaption></figure><p><strong>Reading</strong> <a href="https://en.wikipedia.org/wiki/Real-time_kinematic_positioning" target="_blank" rel="noreferrer">Wikipedia: Real-time kinematic positioning</a></p><h2 id="devices-rovers" tabindex="-1">Devices (Rovers) <a class="header-anchor" href="#devices-rovers" aria-label="Permalink to &quot;Devices (Rovers)&quot;">​</a></h2><p>The <a href="/docs/branch/31d42f615ccbbe66611e36a9fbfe42b065e51be507b5dab276c3de717a9a0d26/devices/rtk/handheld/">RH2</a> and <a href="/docs/branch/31d42f615ccbbe66611e36a9fbfe42b065e51be507b5dab276c3de717a9a0d26/devices/rtk/vehicle">VTRTK</a> support RTK positioning, and support both rover and base station modes.</p><p>In the past, we also offered the RH1, the first Lightbug device to support RTK, which is now discontinued.</p><h2 id="base-stations" tabindex="-1">Base stations <a class="header-anchor" href="#base-stations" aria-label="Permalink to &quot;Base stations&quot;">​</a></h2><p>A base station is a stationary GNSS receiver placed at a precisely surveyed location.</p><p>It continuously collects GNSS observations and computes correction data that represents the difference between its known position and the position computed from GNSS measurements.</p><p>With the Lightbug platform, you are able to bring your own base station, make use of an existing network of stream of data, or use a Lightbug device in base station mode to provide corrections to other Lightbug devices in rover mode.</p><h2 id="correction-data" tabindex="-1">Correction data <a class="header-anchor" href="#correction-data" aria-label="Permalink to &quot;Correction data&quot;">​</a></h2><p>Correction data is the set of messages produced by a base station that describe how satellite measurements should be adjusted so a rover can compute a much more accurate position. Corrections are commonly encoded in RTCM formats and delivered over radio links, cellular/NTRIP streams, or cloud services.</p><p>Options include:</p><ul><li><a href="https://www.swiftnav.com/products/skylark" target="_blank" rel="noreferrer"><strong>Swift Navigation Skylark</strong></a> — we have partnered with Swift Navigation to provide out of the box access to their Skylark service with a six-month free trial of Skylark Precise Positioning Service, providing immediate access to centimeter-level accuracy (<a href="https://www.swiftnav.com/resource/press-release/swift-navigation-and-lightbug-partner-to-deliver-centimeter-level-positioning-for-worker-safety-and-asset-tracking" target="_blank" rel="noreferrer">press release</a>)</li><li><strong>Bring your own (BYO) correction source</strong> — you can use any service or base station that outputs standard RTCM messages and stream them to your devices (for example via NTRIP or a private RTCM server).</li><li><strong>Lightbug device as a base</strong> — an RTK enabled Lightbug device can be configured in base station mode to generate correction streams that other Lightbug devices in rover mode can consume.</li></ul><h2 id="how-it-works-high-level" tabindex="-1">How it works (high level) <a class="header-anchor" href="#how-it-works-high-level" aria-label="Permalink to &quot;How it works (high level)&quot;">​</a></h2><ul><li>A fixed base station sits at a precisely surveyed, known location and collects GNSS observations.</li><li>A rover receiver (the device in the field) receives the same satellite signals and also collects observations.</li><li>The base computes correction data (pseudorange and carrier-phase) representing the difference between its known position and the position computed from GNSS measurements.</li><li>Corrections are transmitted to the rover in real time (commonly using RTCM formats over radio, cellular/NTRIP, or other links).</li><li>The rover applies the corrections and attempts to resolve carrier-phase integer ambiguities, producing a corrected, high-precision fix.</li></ul><h2 id="practical-accuracy-and-limits" tabindex="-1">Practical accuracy and limits <a class="header-anchor" href="#practical-accuracy-and-limits" aria-label="Permalink to &quot;Practical accuracy and limits&quot;">​</a></h2><ul><li>Centimetre-level horizontal accuracy is achievable under good conditions with successful ambiguity resolution.</li><li>Vertical accuracy is usually a bit worse than horizontal and more sensitive to geometry and multipath.</li></ul><h2 id="common-error-sources-and-failure-modes" tabindex="-1">Common error sources and failure modes <a class="header-anchor" href="#common-error-sources-and-failure-modes" aria-label="Permalink to &quot;Common error sources and failure modes&quot;">​</a></h2><ul><li>Multipath: reflected signals (from buildings, water, ground) distort measurements and can prevent ambiguity resolution.</li><li>Signal blockage: buildings, foliage, vehicle bodies or low horizons reduce satellite visibility and degrade fixes.</li><li>Ionospheric and tropospheric delays: residual atmospheric errors increase with baseline; network RTK mitigates this.</li><li>Latency and packet loss: delayed or missing corrections cause the rover to revert to a less accurate solution or lose fix.</li><li>Incorrect base coordinates: if the base station location is wrong, corrections will be biased and produce incorrect rover positions.</li></ul><h2 id="other-terminology" tabindex="-1">Other terminology <a class="header-anchor" href="#other-terminology" aria-label="Permalink to &quot;Other terminology&quot;">​</a></h2><ul><li>RTCM: a common protocol family (RTCM 2.x/3.x) used to encode and stream correction messages.</li><li>NTRIP: Networked Transport of RTCM via Internet Protocol, commonly used to stream corrections over cellular data.</li></ul>',24)])])}const p=a(r,[["render",s]]);export{m as __pageData,p as default};
